  // src/ui/save.js
  function load() {
    try {
      const raw = localStorage.getItem(KEY2);
      if (raw) return sanitizeSave(JSON.parse(raw));
    } catch (e) {
    }
    return null;
  }
  function save() {
    if (app.fresh) return;
    app.S.lastSeen = Date.now();
    try {
      localStorage.setItem(KEY2, JSON.stringify(app.S));
    } catch (e) {
    }
  }
  function exportCode() {
    return btoa(unescape(encodeURIComponent(JSON.stringify(app.S))));
  }
  function importCode(code) {
    const s = sanitizeSave(JSON.parse(decodeURIComponent(escape(atob(code.trim())))));
    if (!s || typeof s !== "object" || !Array.isArray(s.heroes) || !s.items || typeof s.items !== "object") throw new Error(tx("\u683C\u5F0F\u4E0D\u7B26"));
    return s;
  }

  // src/ui/move.js
  var NEW_ORIGIN = "https://raid-leader.anubispaco.workers.dev";
  var OLD_HOSTS = ["anubispaco-tech.github.io"];
  var b64 = (bytes) => {
    let s = "";
    for (let i = 0; i < bytes.length; i += 32768) s += String.fromCharCode(...bytes.subarray(i, i + 32768));
    return btoa(s).replace(/\+/g, "-").replace(/\//g, "_").replace(/=+$/, "");
  };
  var unb64 = (str) => {
    const s = atob(str.replace(/-/g, "+").replace(/_/g, "/"));
    const out = new Uint8Array(s.length);
    for (let i = 0; i < s.length; i++) out[i] = s.charCodeAt(i);
    return out;
  };
  var pipe = async (bytes, stream) => new Uint8Array(await new Response(new Blob([bytes]).stream().pipeThrough(stream)).arrayBuffer());
  async function pack(text) {
    const raw = new TextEncoder().encode(text);
    if (typeof CompressionStream === "function") return "z" + b64(await pipe(raw, new CompressionStream("deflate-raw")));
    return "b" + b64(raw);
  }
  async function unpack(code) {
    const bytes = unb64(code.slice(1));
    return new TextDecoder().decode(code[0] === "z" ? await pipe(bytes, new DecompressionStream("deflate-raw")) : bytes);
  }
  function moveAway() {
    if (!OLD_HOSTS.includes(location.hostname)) return false;
    document.body.insertAdjacentHTML("beforeend", `<div id="boot"><div class="blogo">${tx("\u526F\u672C\u5718\u9577")}</div><div class="bbar"><i></i></div><div class="bmsg">${tx("\u904A\u6232\u642C\u5BB6\u4E86\uFF0C\u6B63\u5728\u5E36\u8457\u4F60\u7684\u9032\u5EA6\u524D\u5F80\u65B0\u7DB2\u5740\u2026")}</div></div>`);
    let raw = null;
    try {
      raw = localStorage.getItem(KEY2);
    } catch (e) {
    }
    const go = (hash2) => location.replace(NEW_ORIGIN + "/" + hash2);
    if (!raw) {
      go("");
      return true;
    }
    pack(raw).then((c) => go("#move=" + c)).catch(() => go(""));
    return true;
  }
  async function takeMoved() {
    const m = /^#move=([A-Za-z0-9_-]+)$/.exec(location.hash);
    if (!m) return null;
    try {
      history.replaceState(null, "", location.pathname + location.search);
    } catch (e) {
    }
    try {
      if (localStorage.getItem(KEY2)) return "kept";
    } catch (e) {
      return "bad";
    }
    try {
      const s = sanitizeSave(JSON.parse(await unpack(m[1])));
      if (!s || typeof s !== "object" || !Array.isArray(s.heroes) || !s.items) return "bad";
      localStorage.setItem(KEY2, JSON.stringify(s));
      return "moved";
    } catch (e) {
      return "bad";
    }
  }

