  // src/ui/icons.js
  var CLASS_GLYPH = { guardian: "templar-shield", cleric: "holy-symbol", rogue: "plain-dagger", mage: "wizard-staff", druid: "oak-leaf", shaman: "totem" };
  var SLOT_GLYPH = { weapon: "broadsword", head: "visored-helm", chest: "breastplate", hands: "gauntlet", legs: "leg-armor", trinket: "gem-pendant" };
  var BOSS_GLYPH = [
    "mushroom-gills",
    "golem-head",
    "trident",
    "fire-shield",
    "crowned-skull",
    "tentacles-skull",
    "dragon-head",
    "rock-golem",
    "anvil-impact",
    "cultist",
    ["sun", "moon"],
    "crystal-growth",
    "portal",
    "horned-skull"
  ];
  var TRASH = "imp-laugh";
  var GOBLIN = "goblin-head";
  var COIN = "two-coins";
  var HORN = "hunting-horn";
  var TROPHY = "trophy-cup";
  var svg = (name, cls2 = "") => icon_data_default[name] ? `<svg class="gi ${cls2}" viewBox="0 0 512 512" aria-hidden="true"><path d="${icon_data_default[name]}"/></svg>` : "";
  var classIcon = (cls2) => svg(CLASS_GLYPH[cls2], "gi-" + cls2);
  var slotIcon = (slot, rarity = 0) => svg(SLOT_GLYPH[slot], "c" + rarity);
  var dungeonIcon = (i) => {
    const g = BOSS_GLYPH[i];
    return svg(Array.isArray(g) ? g[0] : g, "gi-boss");
  };
  var byName = {};
  DUNGEONS.forEach((d, i) => {
    const g = BOSS_GLYPH[i];
    if (d.twin) d.twin.forEach((t, k) => {
      byName[t.name] = Array.isArray(g) ? g[k] : g;
    });
    byName[d.boss] = Array.isArray(g) ? g[0] : g;
  });
  var enemyIcon = (e) => svg(e.goblin ? GOBLIN : e.boss ? byName[e.name] || "crowned-skull" : TRASH, e.boss ? "gi-boss" : "gi-foe");
  function installIcons() {
    for (const [k, p] of Object.entries(CLASSES)) if (CLASS_GLYPH[k]) p.icon = classIcon(k);
    const coin = `data:image/svg+xml,${encodeURIComponent(`<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 512 512"><path d="${icon_data_default[COIN]}"/></svg>`)}`;
    const st = document.createElement("style");
    st.textContent = `.coin{background:var(--brass)!important;border-radius:0!important;width:16px!important;height:16px!important;-webkit-mask:url("${coin}") center/contain no-repeat;mask:url("${coin}") center/contain no-repeat}`;
    document.head.appendChild(st);
  }

  // src/ui/helpers.js
  var $ = (s) => document.querySelector(s);
  var fmt = (n2) => Math.round(n2).toLocaleString("zh-TW");
  var pct = (a, b) => Math.max(0, Math.min(100, 100 * a / b));
  var esc = (s) => String(s ?? "").replace(/[&<>"']/g, (c) => ({ "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;", "'": "&#39;" })[c]);
  var lockMark = (x) => x.locked ? '<span class="lockic" aria-label="locked">\u{1F512}</span>' : "";
  var heroName = (h) => `${lockMark(h)}<span class="c${h.rarity || 0}">${h.legend ? `${LEGENDS[h.cls].title}\u30FB` : ""}${h.name}</span>`;
  var rarityTag = (h) => `<span class="rtag r${h.rarity || 0}">${HERO_RARITY[h.rarity || 0].name}</span>`;
  var mmss = (sec) => `${Math.floor(Math.abs(sec) / 60)}:${String(Math.abs(sec) % 60).padStart(2, "0")}`;
  function toast(msg) {
    const el = $("#toast");
    el.innerHTML = `<div class="toast">${msg}</div>`;
    clearTimeout(toast.t);
    toast.t = setTimeout(() => el.innerHTML = "", 2200);
  }
  var hero = (id) => app.S.heroes.find((h) => h.id === id);
  var cls = (h) => CLASSES[h.cls];
  var inParty = (h) => app.S.party.includes(h.id);
  function itemStatText(it) {
    const p = [tx("\u5A01\u529B {0}", itemPow(it)), tx("\u8010\u529B {0}", itemSta(it))];
    if (it.crit) p.push(tx("\u66B4\u64CA +{0}%", Math.round(it.crit * 100)));
    return p.join(" \xB7 ");
  }
  function itemName(it) {
    return `${slotIcon(it.slot, it.rarity)}${it.set ? '<span class="settag">T0</span>' : ""}<span class="c${it.rarity}">${it.name}</span>${it.up ? `<span class="up">+${it.up}</span>` : ""}${lockMark(it)}`;
  }
  function partyPower() {
    return partyHeroes(app.S).reduce((a, h) => a + heroPower(h, app.S.items), 0);
  }
  function avgPartyIlvl() {
    const p = partyHeroes(app.S);
    return p.length ? Math.round(p.reduce((a, h) => a + heroIlvl(h, app.S.items), 0) / p.length) : 0;
  }
  function avgPartyLv() {
    const p = partyHeroes(app.S);
    return p.length ? Math.round(p.reduce((a, h) => a + h.level, 0) / p.length) : 0;
  }
  var firstWinLine = (fw) => fw ? tx('<div style="color:var(--brass)">\u{1F3C6} \u4ECA\u65E5\u9996\u52DD\uFF1A+{0} \u91D1\u3001{1}</div>', fmt(fw.gold), itemName(fw.item)) : "";
  var dailyOpenNow = () => app.dailyOpen != null ? app.dailyOpen : dailyPending(app.S) > 0;

  // src/core/version.js
  var VERSION = "0.18.0";

  // src/ui/telemetry.js
  var URL_ = TELEMETRY.url;
  var enabled = () => !!URL_;
  var lb = { at: 0, data: null, loading: false, error: false };
  function post(body, keepalive = false) {
    if (!URL_ || !app.S) return Promise.resolve(null);
    const p = app.S.player;
    return fetch(URL_, {
      method: "POST",
      keepalive,
      headers: { "Content-Type": "text/plain;charset=utf-8" },
      body: JSON.stringify({ pid: p.pid, name: p.name || tx("\u533F\u540D"), ver: VERSION, ...body })
    }).then((r) => r.json()).catch(() => null);
  }
  function progress() {
    const S = app.S, party = partyHeroes(S);
    const top = Math.max(0, ...Object.keys(S.clears).filter((k) => S.clears[k]).map((k) => +k + 1));
    const best = mythicBestLevel(S, 1), best2 = mythicBestLevel(S, 2);
    return {
      level: party.length ? Math.round(party.reduce((a, h) => a + h.level, 0) / party.length) : 1,
      top,
      key: mythicUnlocked(S) ? S.mythic.key : 0,
      best,
      key2: tierUnlocked(S, 2) ? S.mythic.key2 : 0,
      best2,
      playMin: Math.round(S.player.playSec / 60)
    };
  }
  var progressText = () => {
    const p = progress();
    return tx("Lv{0}\u30FB\u7B2C {1} \u5C64{2}", p.level, p.top, (p.best ? tx("\u30FB\u79D8\u5883 +{0}", p.best) : "") + (p.best2 ? tx("\u30FB\u6DF1\u6DF5 +{0}", p.best2) : ""));
  };
  var sendSnapshot = (keepalive) => post({ type: "snapshot", ...progress() }, keepalive);
  var sendEvent = (kind, detail) => post({ type: "event", kind, detail });
  var sendFeedback = (text) => post({ type: "feedback", text, progress: progressText() });
  function leaderboard() {
    if (!URL_) return null;
    const fresh = Date.now() - lb.at < TELEMETRY.leaderboardSec * 1e3;
    if (!fresh && !lb.loading) {
      lb.loading = true;
      fetch(URL_ + "?action=leaderboard").then((r) => r.json()).then((d) => {
        lb.data = d.ok ? d.list : lb.data;
        lb.error = !d.ok;
      }).catch(() => {
        lb.error = true;
      }).finally(() => {
        lb.at = Date.now();
        lb.loading = false;
        if (app.tab === "dungeon") app.render(true);
      });
    }
    return lb;
  }
  var sinceSnap = 0;
  function tick(sec) {
    if (!app.S) return;
    app.S.player.playSec += sec;
    sinceSnap += sec;
    if (sinceSnap >= TELEMETRY.snapshotMin * 60) {
      sinceSnap = 0;
      sendSnapshot();
    }
  }

  // src/ui/news.js
  var URL_2 = TELEMETRY.url;
  var LS = "raid-leader-news";
  var READ = "raid-leader-news-read";
  var POP = "raid-leader-news-pop";
  var REFRESH_MS = 10 * 60 * 1e3;
  var get = (k, d) => {
    try {
      return JSON.parse(localStorage.getItem(k) || "null") ?? d;
    } catch (e) {
      return d;
    }
  };
  var put = (k, v) => {
    try {
      localStorage.setItem(k, JSON.stringify(v));
    } catch (e) {
    }
  };
  var cached = get(LS, {});
  var news = { list: Array.isArray(cached.list) ? cached.list : [], at: Number(cached.at) || 0, loading: false };
  var TYPE_CLASS = { \u516C\u544A: "n-info", \u6D3B\u52D5: "n-event", \u66F4\u65B0: "n-update", \u7DAD\u4FEE: "n-maint" };
  var typeLabel = (t) => ({ \u516C\u544A: tx("\u516C\u544A"), \u6D3B\u52D5: tx("\u6D3B\u52D5"), \u66F4\u65B0: tx("\u66F4\u65B0"), \u7DAD\u4FEE: tx("\u7DAD\u4FEE") })[t] || tx("\u516C\u544A");
  var cmpVer = (a, b) => {
    const x = String(a).split(".").map(Number), y = String(b).split(".").map(Number);
    for (let i = 0; i < 3; i++) {
      const d = (x[i] || 0) - (y[i] || 0);
      if (d) return d;
    }
    return 0;
  };
  var now = () => Date.now();
  var live = () => news.list.filter((n2) => (!n2.start || n2.start <= now()) && (!n2.end || n2.end > now()));
  var readIds = () => get(READ, []);
  var unread = () => {
    const r = readIds();
    return live().filter((n2) => !r.includes(n2.id)).length;
  };
  var tooOld = (n2) => n2.minVer && cmpVer(n2.minVer, VERSION) > 0;
