    return tx("\u63D0\u793A\uFF1A\u56DE\u524D\u4E00\u5C64\u5237\u88DD\u5099\u8207\u7B49\u7D1A\uFF0C\u6216\u6309\u300C\u5099\u6230\u300D\u63DB\u500B\u9663\u5BB9\u3002");
