  // src/ui/battle-runner.js
  function startBattle(dIdx) {
    const p = partyHeroes(app.S);
    if (!p.length) {
      toast(tx("\u968A\u4F0D\u6C92\u6709\u6210\u54E1"));
      app.tab = "team";
      app.render();
      return;
    }
    clearTimeout(app.pendingRepeat);
    app.pendingRepeat = null;
    app.battle = new Battle(p, app.S.items, dIdx, { autoHorn: app.S.idle === dIdx });
    app.lastResult = null;
    app.battle.push(tx("\u9032\u5165 {0}\uFF0C\u7B2C 1 \u6CE2\u6575\u4EBA\u51FA\u73FE", DUNGEONS[dIdx].name), "info");
    runTimer();
  }
  function startMythic(dIdx) {
    const p = partyHeroes(app.S);
    if (!p.length) {
      toast(tx("\u968A\u4F0D\u6C92\u6709\u6210\u54E1"));
      app.tab = "team";
      app.render();
      return;
    }
    clearTimeout(app.pendingRepeat);
    app.pendingRepeat = null;
    const o = mythicBattleOpts(dIdx, keyOf(app.S, dIdx));
    app.battle = new Battle(p, app.S.items, dIdx, o);
    app.lastResult = null;
    app.battle.push(tx("\u9032\u5165{3}\uFF1A{0} +{1}\uFF5C\u8A5E\u7DB4\uFF1A{2}", DUNGEONS[dIdx].name, o.mythic.level, o.mythic.affixes.map((a) => AFFIXES[a].name).join(tx("\u3001")), o.mythic.tier === 2 ? tx("\u6DF1\u6DF5\u79D8\u5883") : tx("\u50B3\u5947\u79D8\u5883")), "info");
    runTimer();
  }
  function startMythicIdle(dIdx) {
    const p = partyHeroes(app.S), lv = mythicIdleLevel(app.S, dIdx);
    if (!p.length || !lv) return;
    clearTimeout(app.pendingRepeat);
    app.pendingRepeat = null;
    const o = mythicBattleOpts(dIdx, lv);
    app.battle = new Battle(p, app.S.items, dIdx, { ...o, autoHorn: true });
    app.battle.mythicIdle = true;
    app.lastResult = null;
    app.battle.push(tx("\u79D8\u5883\u639B\u6A5F\uFF1A{0} +{1}\uFF08\u9470\u77F3\u4E0D\u8B8A\uFF0C\u734E\u52F5 {2}%\uFF09", DUNGEONS[dIdx].name, lv, Math.round(MYTHIC.idleMult * 100)), "info");
    runTimer();
  }
  function startVault(floor) {
    const p = partyHeroes(app.S), floors = vaultFloors(app.S);
    if (!floors.includes(floor)) floor = floors[floors.length - 1];
    if (floor == null) return false;
    if (!p.length) {
      toast(tx("\u968A\u4F0D\u6C92\u6709\u6210\u54E1"));
      app.tab = "team";
      app.render();
      return false;
    }
    if (!vaultLeft(app.S)) {
      toast(tx("\u4ECA\u5929\u7684\u5BF6\u5EAB\u6B21\u6578\u7528\u5B8C\u4E86\uFF0C\u660E\u5929 00:00 \u91CD\u7F6E"));
      return false;
    }
    clearTimeout(app.pendingRepeat);
    app.pendingRepeat = null;
    app.battle = new Battle(p, app.S.items, floor, vaultBattleOpts(floor));
    app.lastResult = null;
    app.battle.push(tx("\u9032\u5165\u5BF6\u5EAB\u7B2C {0} \u5C64\uFF1A60 \u79D2\u5167\u6253\u5012\u8D8A\u591A\u5BF6\u85CF\u54E5\u5E03\u6797\uFF0C\u91D1\u5E63\u8D8A\u591A\uFF01", floor + 1), "info");
    runTimer();
    return true;
  }
  function runTimer() {
    clearInterval(app.bTimer);
    app.bTimer = setInterval(stepBattle, TICK_MS / app.speed);
  }
  function stepBattle() {
    if (!app.battle || app.battle.over) {
      clearInterval(app.bTimer);
      return;
    }
    app.battle.step();
    if (app.battle.over) finishBattle();
    else if (app.tab === "battle") app.render(true);
    else app.renderTabs();
  }
  function finishBattle() {
    clearInterval(app.bTimer);
    const pb = app.battle.mythic ? (app.S.mythic.best[app.battle.dIdx] || {}).level || 0 : 0;
    app.lastResult = app.battle.vault ? applyVaultResult(app.S, app.battle, partyHeroes) : app.battle.mythicIdle ? applyMythicIdleResult(app.S, app.battle) : app.battle.mythic ? applyMythicResult(app.S, app.battle) : applyResult(app.S, app.battle.dIdx, app.battle);
    dailyAfterBattle(app.S, app.battle, app.lastResult);
    save();
    const r = app.lastResult, b = app.battle;
    if (r.first || b.mythic && !b.mythicIdle && r.record && b.mythic.level > pb) milestone();
    for (const m of newBagMilestones(app.S)) setTimeout(() => toast(tx("\u{1F392} {0}\uFF1A\u80CC\u5305 +{1} \u683C", m.name, BAG_PER_MILESTONE)), 400);
    if (b.vault) sendEvent(tx("\u5BF6\u5EAB"), tx("\u7B2C {0} \u5C64 \u6253\u5012 {1} \u96BB +{2} \u91D1", b.vault.floor + 1, r.kills, r.gold));
    else if (b.mythicIdle) {
    } else if (b.mythic) {
      const m = app.mBuf || (app.mBuf = { n: 0, timed: 0, fail: 0 });
      m.n++;
      if (r.inTime) m.timed++;
      else if (!b.win) m.fail++;
      if (r.record) sendEvent(tx("\u79D8\u5883"), `${DUNGEONS[b.dIdx].name} +${b.mythic.level} ${tx("\u9650\u6642")} ${mmss(b.tick)}${tx("\uFF08\u65B0\u7D00\u9304\uFF09")}`);
      if (m.n >= 10) {
        sendEvent(tx("\u79D8\u5883"), tx("\u8FD1 {0} \u5834\uFF1A\u9650\u6642 {1}\u30FB\u5931\u6557 {2}\u30FB\u76EE\u524D\u9470\u77F3 +{3}", m.n, m.timed, m.fail, keyOf(app.S, b.dIdx)));
        app.mBuf = null;
      }
    } else if (r.first) sendEvent(tx("\u9996\u901A"), tx("\u7B2C {0} \u5C64 {1}", b.dIdx + 1, DUNGEONS[b.dIdx].name));
    if (!app.battle.mythic && !app.battle.vault && app.S.idle === app.battle.dIdx) {
      const d = app.battle.dIdx;
      app.pendingRepeat = setTimeout(() => {
        app.pendingRepeat = null;
        if (app.S.idle === d) startBattle(d);
      }, 3e3);
    }
    if (b.mythicIdle && app.S.idleMythic === b.dIdx) {
      const d = b.dIdx;
      app.pendingRepeat = setTimeout(() => {
        app.pendingRepeat = null;
        if (app.S.idleMythic === d) startMythicIdle(d);
      }, 3e3);
    }
    app.render(true);
    if (!b.mythic && !b.vault && app.showStuck) app.showStuck("battle");
    if (r.first && app.storyOnce) app.storyOnce("post" + b.dIdx);
  }

  // src/ui/main.js
  var ICONS = {
    dungeon: '<path d="M4 20V9l8-5 8 5v11"/><path d="M9 20v-6a3 3 0 0 1 6 0v6"/>',
    battle: '<path d="M5 19 19 5M14 5h5v5M5 14l5 5M4 20l3-3"/>',
    team: '<circle cx="9" cy="8" r="3"/><circle cx="17" cy="9" r="2.4"/><path d="M3 19c.6-3.4 3-5 6-5s5.4 1.6 6 5M15 14.5c2.6-.3 4.8 1.2 5.5 4.5"/>',
    bag: '<path d="M6 8h12l-1 12H7L6 8Z"/><path d="M9 8V6a3 3 0 0 1 6 0v2"/>',
    tavern: '<path d="M6 4h10v4a5 5 0 0 1-10 0V4Z"/><path d="M16 5h2a2 2 0 0 1 0 4h-2M11 13v4M7 20h8"/>'
  };
  var TABS = [["dungeon", tx("\u526F\u672C")], ["battle", tx("\u6230\u9B25")], ["team", tx("\u5718\u968A")], ["bag", tx("\u80CC\u5305")], ["tavern", tx("\u9152\u9928")]];
  function renderTabs() {
    $("#tabs").innerHTML = TABS.map(([k, n2]) => `<button data-tab="${k}" class="${app.tab === k ? "sel" : ""}" aria-label="${n2}"><svg viewBox="0 0 24 24">${ICONS[k]}</svg>${n2}${k === "battle" && app.battle && !app.battle.over && app.tab !== "battle" || k === "bag" && app.S.stash.length || k === "team" && app.S.heroes.some((h) => pendingPicks(h)) ? '<span class="dot"></span>' : ""}</button>`).join("");
  }
  function render(skipModal) {
    achToasts();
    $("#gold").textContent = fmt(app.S.gold);
    $("#idleChip").hidden = !partyLocked(app.S);
    renderTabs();
    tutTick();
    const v = $("#view");
    if (app.tab === "dungeon") v.innerHTML = viewDungeons();
    if (app.tab === "battle") v.innerHTML = viewBattle();
    if (app.tab === "team") v.innerHTML = viewTeam();
    if (app.tab === "bag") v.innerHTML = viewBag();
    if (app.tab === "tavern") v.innerHTML = viewTavern();
    if (app.tab === "battle") {
      const lg = $(".log");
      if (lg) lg.scrollTop = lg.scrollHeight;
    } else if (tutActive(app.S) && !app.fresh) v.insertAdjacentHTML("afterbegin", coachCard());
    tutHighlight();
    if (!skipModal) renderModal();
  }
  function tutTick() {
    if (app.fresh) return;
    const done = tutAdvance(app.S);
    if (!done.length) return;
    save();
    for (const id of done) sendEvent(tx("\u6559\u5B78"), id);
    if (done.includes("finish")) setTimeout(() => toast(tx("\u{1F389} \u65B0\u624B\u6559\u5B78\u5B8C\u6210\uFF01\u7372\u5F97 {0} \u91D1", TUT_REWARD.gold)), 300);
  }
  function coachCard() {
    const st = tutCurrent(app.S);
    if (!st) return "";
    const i = app.S.tut.step, n2 = TUTORIAL.length;
    return tx('<div class="coach"><div class="cstep num">{0}/{1}</div><div class="cbody"><b>{2}</b><span>{3}</span></div><button class="linkbtn cskip" data-act="tutskip">\u8DF3\u904E\u6559\u5B78</button></div>', i + 1, n2, st.text, st.sub);
  }
